import React, { useState, useEffect } from 'react';
import { getAllRestaurants } from '../../services/api';
import { useNavigate } from 'react-router-dom';

const RestaurantList = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadRestaurants();
    const interval = setInterval(loadRestaurants, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadRestaurants = async () => {
    try {
      const response = await getAllRestaurants();
      setRestaurants(response.data);
    } catch (error) {
      console.error('Error loading restaurants:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredRestaurants = restaurants.filter(r =>
    r.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.cuisine_type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <Loading />;

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Discover Restaurants</h1>
        <p style={styles.subtitle}>Find & reserve your favorite dining spots</p>

        <div style={styles.searchContainer}>
          <input
            type="text"
            placeholder="Search by name, cuisine, or location..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={styles.searchInput}
          />
          {searchTerm && <button onClick={() => setSearchTerm('')} style={styles.clearBtn}>✕</button>}
        </div>

        <div style={styles.statsBar}>
          <div>Restaurants: <strong>{restaurants.length}</strong></div>
          <div>Avg Rating: <strong>⭐ 4.8</strong></div>
          <button onClick={loadRestaurants} style={styles.refreshBtn}>Refresh 🔄</button>
        </div>
      </header>

      {filteredRestaurants.length === 0 ? (
        <EmptyState searchTerm={searchTerm} />
      ) : (
        <ul style={styles.list}>
          {filteredRestaurants.map(restaurant => (
            <li
              key={restaurant.id}
              style={styles.listItem}
              onClick={() => navigate(`/restaurant/${restaurant.id}`)}
            >
              <img
                src={restaurant.image_url || 'https://via.placeholder.com/120x80?text=Food'}
                alt={restaurant.name}
                style={styles.thumb}
              />
              <div style={styles.info}>
                <h3 style={styles.name}>{restaurant.name}</h3>
                <p style={styles.cuisine}>{restaurant.cuisine_type}</p>
                <p style={styles.address}>📍 {restaurant.address.split(',')[0]}</p>
                <p style={styles.hours}>🕒 {restaurant.opening_time} - {restaurant.closing_time}</p>
              </div>
              <div style={styles.action}>
                <button style={styles.reserveBtn}>Reserve →</button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

// --- small reusable components ---
const Loading = () => (
  <div style={styles.loadingContainer}>
    <div style={styles.spinner}></div>
    <p style={styles.loadingText}>Loading restaurants...</p>
  </div>
);

const EmptyState = ({ searchTerm }) => (
  <div style={styles.emptyState}>
    <span style={styles.emptyIcon}>🍽️</span>
    <h2 style={styles.emptyTitle}>No restaurants found</h2>
    <p style={styles.emptyText}>
      {searchTerm ? 'Try a different search term' : 'Check back soon for new restaurants!'}
    </p>
  </div>
);

// --- styles ---
const styles = {
  container: { padding: '2rem', fontFamily: 'sans-serif', background: '#f9f9f9', minHeight: '100vh' },
  header: { marginBottom: '2rem', textAlign: 'center' },
  title: { fontSize: '2.5rem', marginBottom: '0.25rem', color: '#333' },
  subtitle: { fontSize: '1.2rem', color: '#666', marginBottom: '1.5rem' },
  searchContainer: { position: 'relative', maxWidth: '500px', margin: '0 auto 1rem' },
  searchInput: { width: '100%', padding: '0.75rem 2.5rem 0.75rem 1rem', borderRadius: '25px', border: '1px solid #ccc', outline: 'none', fontSize: '1rem' },
  clearBtn: { position: 'absolute', right: '0.5rem', top: '0.25rem', border: 'none', background: 'transparent', cursor: 'pointer', fontSize: '1rem' },
  statsBar: { display: 'flex', justifyContent: 'center', gap: '1.5rem', marginTop: '0.5rem', fontSize: '1rem' },
  refreshBtn: { cursor: 'pointer', border: 'none', background: '#667eea', color: 'white', padding: '0.25rem 0.75rem', borderRadius: '5px' },
  list: { listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: '1rem' },
  listItem: { display: 'flex', alignItems: 'center', background: 'white', padding: '1rem', borderRadius: '12px', boxShadow: '0 3px 10px rgba(0,0,0,0.1)', cursor: 'pointer', transition: 'transform 0.2s', gap: '1rem' },
  listItemHover: { transform: 'translateY(-3px)' },
  thumb: { width: '120px', height: '80px', objectFit: 'cover', borderRadius: '8px' },
  info: { flex: 1 },
  name: { fontSize: '1.25rem', margin: 0, fontWeight: '600' },
  cuisine: { margin: '0.25rem 0', color: '#667eea' },
  address: { margin: '0.25rem 0', color: '#555', fontSize: '0.9rem' },
  hours: { margin: '0.25rem 0', color: '#555', fontSize: '0.9rem' },
  action: {},
  reserveBtn: { background: '#764ba2', color: 'white', border: 'none', padding: '0.5rem 1rem', borderRadius: '8px', cursor: 'pointer' },
  loadingContainer: { display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' },
  spinner: { width: '50px', height: '50px', border: '5px solid #e0e0e0', borderTop: '5px solid #667eea', borderRadius: '50%', animation: 'spin 1s linear infinite' },
  loadingText: { marginTop: '1rem', color: '#333' },
  emptyState: { textAlign: 'center', marginTop: '4rem', color: '#666' },
  emptyIcon: { fontSize: '4rem', display: 'block', marginBottom: '1rem' },
  emptyTitle: { fontSize: '1.8rem', marginBottom: '0.5rem' },
  emptyText: { fontSize: '1rem' }
};

export default RestaurantList;
